180		paid := true
181		var err error
182		switch {
183		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
184			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
185		case plan.UsageType == store.Licensed:
186			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
187		}
188		if err != nil {
189			return err
190		}
191		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
192			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
193			if paid {
194				x.Status = store.Active
195			} else {
196				x.Status = store.PastDue
197			}
198			return nil
199		})
200		if err != nil {
201			return err
202		}
203		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
204		return nil
205	}
