// ClaimPeriod moves a subscription on from the period that ends at periodEnd, changing it with f. It is a compare-and-set:
// when the subscription is canceled or is no longer in that period (another renewal moved it on), it changes nothing and
// reports false. Of several renewals of the same period, only the first one claims it.
func (s *Store) ClaimPeriod(orgID, id string, periodEnd time.Time, f func(*Subscription) error) (Subscription, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, false, ErrNotFound
	}
	if old.Status == Canceled || !old.CurrentPeriodEnd.Equal(periodEnd) {
		return copySub(old), false, nil
	}
	sub, err := s.applySubLocked(old, f)
	if err != nil {
		return Subscription{}, false, err
	}
	s.subs[id] = sub
	return copySub(sub), true, nil
}

