// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due; when the gateway is unavailable the subscription still moves on, its invoice stays open and its status is kept.
//
// A period is renewed at most once, however many RenewDue calls run and whether they overlap: the renewal claims the period
// before it invoices anything. A subscription that fails does not stop the others; RenewDue returns the errors after trying
// them all. It returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew renews one due subscription. It reports whether the subscription moved on (renewed or canceled), which can be true
// together with an error when the period was claimed but its invoice could not be charged.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		canceled, claimed, err := s.Store.ClaimPeriod(sub.OrgID, sub.ID, sub.CurrentPeriodEnd, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err != nil || !claimed {
			return false, err
		}
		s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
		return true, nil
	}

	// Claim the new period before anything is invoiced. Only the renewal that claims it invoices it, so a period is invoiced
	// once, and a gateway failure after the claim cannot leave the subscription due again.
	start := now
	end := billing.AddInterval(start, plan.Interval)
	renewed, claimed, err := s.Store.ClaimPeriod(sub.OrgID, sub.ID, sub.CurrentPeriodEnd, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		return nil
	})
	if err != nil || !claimed {
		return false, err
	}

	inv, invoiced, err := s.renewalInvoice(ctx, sub, plan, start, end)
	if err != nil {
		// Nothing was invoiced: give the period back so that the next run tries again.
		_, _, _ = s.Store.ClaimPeriod(sub.OrgID, sub.ID, end, func(x *store.Subscription) error {
			x.CurrentPeriodStart, x.CurrentPeriodEnd = sub.CurrentPeriodStart, sub.CurrentPeriodEnd
			return nil
		})
		return false, err
	}

	// The status follows the charge. With no invoice to charge, the subscription is in good standing.
	status, settled := store.Active, true
	if invoiced {
		var paid bool
		paid, err = s.chargeInvoice(ctx, inv)
		switch {
		case errors.Is(err, payments.ErrUnavailable):
			settled = false
		case err != nil:
		case !paid:
			status = store.PastDue
		}
	}
	updated, uerr := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		if settled && x.Status != store.Canceled {
			x.Status = status
		}
		return nil
	})
	if uerr != nil {
		err = errors.Join(err, uerr)
	} else {
		s.publish(ctx, sub.OrgID, "subscription.updated", updated)
	}
	return renewed, err
}

// renewalInvoice creates the invoice for the period a renewal starts. A licensed plan bills the new period (start to end) in
// advance; a metered plan bills the usage of the period that ended, which is the subscription's current period, except while
// it is trialing. It reports false when there is nothing to invoice.
func (s *Service) renewalInvoice(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (store.Invoice, bool, error) {
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		inv, err := s.createPeriodInvoice(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		return inv, err == nil, err
	case plan.UsageType == store.Licensed:
		inv, err := s.createPeriodInvoice(ctx, sub, plan, start, end)
		return inv, err == nil, err
	}
	return store.Invoice{}, false, nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	inv, err := s.createPeriodInvoice(ctx, sub, plan, start, end)
	if err != nil {
		return false, err
	}
	return s.chargeInvoice(ctx, inv)
}

// createPeriodInvoice stores the open invoice of one period of a subscription.
func (s *Service) createPeriodInvoice(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (store.Invoice, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	return inv, nil
}

// chargeInvoice charges an open invoice to the customer's default payment method. It reports false when the charge was
// declined. When the gateway is unavailable the error wraps payments.ErrUnavailable and the invoice stays open.
func (s *Service) chargeInvoice(ctx context.Context, inv store.Invoice) (bool, error) {
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

