// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due; when the gateway is unavailable the subscription still moves on, its invoice stays open and its status is kept.
//
// A period is renewed at most once, however many RenewDue calls run and whether they overlap: the renewal claims the period
// before it invoices anything. A subscription that fails does not stop the others; RenewDue returns the errors after trying
// them all. It returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
