// subscribe starts a monthly team subscription for a new customer of Acme, charged to the card pm at the start, and
// returns it.
func subscribe(t *testing.T, e *apitest.Env, email, pm string) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", email)
	setCard(t, e, c.ID, pm)
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

// setCard makes pm the customer's default payment method.
func setCard(t *testing.T, e *apitest.Env, customerID, pm string) {
	t.Helper()
	if _, err := e.Store.UpdateCustomer(e.Acme.ID, customerID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil }); err != nil {
		t.Fatal(err)
	}
}

func TestConcurrentRenewDueInvoicesEachPeriodOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	var subs []store.Subscription
	for i := range 3 {
		subs = append(subs, subscribe(t, e, fmt.Sprintf("jane%d@example.com", i), "pm_card_visa"))
	}
	e.Clock.Set(subs[0].CurrentPeriodEnd)

	// Eight runs at once, as two server instances and their retries would make them.
	var wg sync.WaitGroup
	var mu sync.Mutex
	total := 0
	var errs []error
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := e.Subs.RenewDue(ctx)
			mu.Lock()
			defer mu.Unlock()
			total += n
			if err != nil {
				errs = append(errs, err)
			}
		}()
	}
	wg.Wait()
	if len(errs) != 0 || total != len(subs) {
		t.Fatalf("renewed %d subscriptions, want %d; errors: %v", total, len(subs), errs)
	}
	for _, sub := range subs {
		invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
		if len(invs) != 2 || invs[1].Status != store.InvoicePaid || !invs[1].PeriodStart.Equal(e.Clock.Now()) {
			t.Fatalf("invoices of %s = %+v, want the first and one renewal", sub.ID, invs)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 2*len(subs) {
		t.Fatalf("charges = %d, want %d (one per invoice)", len(cs), 2*len(subs))
	}
}

func TestGatewayDownStillMovesThePeriodOn(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribe(t, e, "jane@example.com", "pm_card_visa")
	setCard(t, e, sub.CustomerID, "pm_gateway_down")
	e.Clock.Set(sub.CurrentPeriodEnd)

	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(e.Clock.Now()) || !got.CurrentPeriodEnd.Equal(e.Clock.Now().AddDate(0, 1, 0)) {
		t.Fatalf("after the outage = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want the renewal open", invs)
	}

	// The period is not invoiced again, and the open invoice is not charged by RenewDue.
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 0 {
		t.Fatalf("RenewDue again = %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d after a repeated run, want 2", len(invs))
	}

	// The next period is invoiced as usual once the gateway is back.
	setCard(t, e, sub.CustomerID, "pm_card_visa")
	e.Clock.Set(got.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue next period = %d, %v", n, err)
	}
	invs = e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 || invs[1].Status != store.InvoiceOpen || invs[2].Status != store.InvoicePaid {
		t.Fatalf("invoices = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2", len(cs))
	}
}

func TestGatewayDownKeepsThePastDueStatus(t *testing.T) {
	e := apitest.New(t)
	sub := subscribe(t, e, "jane@example.com", "pm_card_declined")
	if sub.Status != store.PastDue {
		t.Fatalf("subscription = %+v, want past due", sub)
	}
	setCard(t, e, sub.CustomerID, "pm_gateway_down")
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(context.Background()); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.PastDue || !got.CurrentPeriodStart.Equal(e.Clock.Now()) {
		t.Fatalf("after the outage = %+v, want past due in the next period", got)
	}
}

func TestDeclinedRenewalIsPastDueAndInvoicedOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribe(t, e, "jane@example.com", "pm_card_visa")
	setCard(t, e, sub.CustomerID, "pm_card_declined")
	e.Clock.Set(sub.CurrentPeriodEnd)

	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.PastDue {
		t.Fatalf("after the decline = %+v, want past due", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v", invs)
	}
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 0 {
		t.Fatalf("RenewDue again = %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d after a repeated run, want 2", len(invs))
	}
}

func TestFailingRenewalDoesNotStopTheOthers(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	// This subscription's customer belongs to Globex, so its renewal invoice cannot be created.
	stranger := e.CreateCustomer(e.Globex, "Sam", "sam@example.com")
	bad, err := e.Store.CreateSubscription(store.Subscription{OrgID: e.Acme.ID, CustomerID: stranger.ID, PlanID: p.ID, Quantity: 1,
		Status: store.Active, StartedAt: now, CurrentPeriodStart: now, CurrentPeriodEnd: now.AddDate(0, 1, 0)}, now)
	if err != nil {
		t.Fatal(err)
	}
	good := subscribe(t, e, "jane@example.com", "pm_card_visa")
	e.Clock.Set(good.CurrentPeriodEnd)

	n, err := e.Subs.RenewDue(ctx)
	if !errors.Is(err, store.ErrCustomerOrgMismatch) || n != 1 {
		t.Fatalf("RenewDue = %d, %v; want 1 renewal and the failure", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: good.ID}); len(invs) != 2 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("the other subscription's invoices = %+v", invs)
	}
	// The failed renewal gave its period back, so the next run tries it again.
	if got, _ := e.Store.Subscription(e.Acme.ID, bad.ID); !got.CurrentPeriodEnd.Equal(bad.CurrentPeriodEnd) {
		t.Fatalf("the failed subscription moved on: %+v", got)
	}
}
